import java.util.*;

class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        List<List<String>> result = new ArrayList<>();
        if (!wordSet.contains(endWord)) return result;
        Map<String, List<String>> parents = new HashMap<>();
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        visited.add(beginWord);
        boolean found = false;
        while (!queue.isEmpty() && !found) {
            Set<String> levelVisited = new HashSet<>();
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String word = queue.poll();
                char[] chars = word.toCharArray();
                for (int j = 0; j < chars.length; j++) {
                    char orig = chars[j];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == orig) continue;
                        chars[j] = c;
                        String next = new String(chars);
                        if (wordSet.contains(next) && !visited.contains(next)) {
                            if (next.equals(endWord)) found = true;
                            levelVisited.add(next);
                            parents.computeIfAbsent(next, k -> new ArrayList<>()).add(word);
                            if (!queue.contains(next) && !visited.contains(next)) {
                                // Only add to queue once per level
                            }
                        }
                    }
                    chars[j] = orig;
                }
            }
            for (String w : levelVisited) {
                queue.offer(w);
                visited.add(w);
            }
        }
        if (found) {
            LinkedList<String> path = new LinkedList<>();
            path.addFirst(endWord);
            buildPaths(parents, beginWord, endWord, path, result);
        }
        return result;
    }

    private void buildPaths(Map<String, List<String>> parents, String beginWord, String word, LinkedList<String> path, List<List<String>> result) {
        if (word.equals(beginWord)) {
            result.add(new ArrayList<>(path));
            return;
        }
        if (!parents.containsKey(word)) return;
        for (String parent : parents.get(word)) {
            path.addFirst(parent);
            buildPaths(parents, beginWord, parent, path, result);
            path.removeFirst();
        }
    }
}

import java.util.*;

class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        List<List<String>> result = new ArrayList<>();
        if (!wordSet.contains(endWord)) return result;
        Map<String, Integer> distance = new HashMap<>();
        Map<String, List<String>> children = new HashMap<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        distance.put(beginWord, 0);
        boolean found = false;
        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            for (int q = 0; q < size; q++) {
                String word = queue.poll();
                int curDist = distance.get(word);
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char orig = chars[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == orig) continue;
                        chars[i] = c;
                        String next = new String(chars);
                        if (!wordSet.contains(next)) continue;
                        if (!distance.containsKey(next)) {
                            distance.put(next, curDist + 1);
                            queue.offer(next);
                            if (next.equals(endWord)) found = true;
                        }
                        if (distance.containsKey(next) && distance.get(next) == curDist + 1) {
                            children.computeIfAbsent(word, k -> new ArrayList<>()).add(next);
                        }
                    }
                    chars[i] = orig;
                }
            }
        }
        if (found) {
            List<String> path = new ArrayList<>();
            path.add(beginWord);
            dfs(children, beginWord, endWord, path, result);
        }
        return result;
    }

    private void dfs(Map<String, List<String>> children, String word, String endWord, List<String> path, List<List<String>> result) {
        if (word.equals(endWord)) {
            result.add(new ArrayList<>(path));
            return;
        }
        List<String> next = children.get(word);
        if (next == null) return;
        for (String child : next) {
            path.add(child);
            dfs(children, child, endWord, path, result);
            path.remove(path.size() - 1);
        }
    }
}
